-- Run in a NEW Oracle APEX workspace/schema. Oracle Database 19c+.
CREATE TABLE sp_categories (category_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_name VARCHAR2(80) NOT NULL UNIQUE);
CREATE TABLE sp_customers (customer_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_name VARCHAR2(120) NOT NULL, email VARCHAR2(180), city VARCHAR2(80), joined_on DATE DEFAULT SYSDATE);
CREATE TABLE sp_products (product_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, category_id NUMBER NOT NULL REFERENCES sp_categories(category_id), product_name VARCHAR2(140) NOT NULL, sku VARCHAR2(30) UNIQUE, unit_price NUMBER(12,2) NOT NULL CHECK(unit_price>=0), stock_qty NUMBER DEFAULT 0 NOT NULL CHECK(stock_qty>=0), is_active CHAR(1) DEFAULT 'Y' CHECK(is_active IN ('Y','N')));
CREATE TABLE sp_orders (order_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, customer_id NUMBER NOT NULL REFERENCES sp_customers(customer_id), order_date DATE DEFAULT SYSDATE NOT NULL, order_status VARCHAR2(20) DEFAULT 'PAID' NOT NULL CHECK(order_status IN ('PAID','PENDING','CANCELLED','REFUNDED')), payment_method VARCHAR2(30), notes VARCHAR2(400));
CREATE TABLE sp_order_items (order_item_id NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, order_id NUMBER NOT NULL REFERENCES sp_orders(order_id) ON DELETE CASCADE, product_id NUMBER NOT NULL REFERENCES sp_products(product_id), quantity NUMBER NOT NULL CHECK(quantity>0), unit_price NUMBER(12,2) NOT NULL CHECK(unit_price>=0));
CREATE INDEX sp_orders_date_ix ON sp_orders(order_date);
CREATE INDEX sp_orders_customer_ix ON sp_orders(customer_id);
CREATE INDEX sp_items_order_ix ON sp_order_items(order_id);
CREATE OR REPLACE VIEW sp_order_summary AS
SELECT o.order_id, o.order_date, o.order_status, o.payment_method, o.customer_id, c.customer_name,
       NVL(SUM(i.quantity*i.unit_price),0) order_total, NVL(SUM(i.quantity),0) units
FROM sp_orders o JOIN sp_customers c ON c.customer_id=o.customer_id
LEFT JOIN sp_order_items i ON i.order_id=o.order_id
GROUP BY o.order_id,o.order_date,o.order_status,o.payment_method,o.customer_id,c.customer_name;
CREATE OR REPLACE VIEW sp_sales_daily AS
SELECT TRUNC(order_date) sales_date, COUNT(*) orders_count, SUM(order_total) revenue
FROM sp_order_summary WHERE order_status='PAID' GROUP BY TRUNC(order_date);
CREATE OR REPLACE VIEW sp_sales_by_category AS
SELECT c.category_name, SUM(i.quantity) units_sold, SUM(i.quantity*i.unit_price) revenue
FROM sp_orders o JOIN sp_order_items i ON i.order_id=o.order_id
JOIN sp_products p ON p.product_id=i.product_id JOIN sp_categories c ON c.category_id=p.category_id
WHERE o.order_status='PAID' GROUP BY c.category_name;
